target.css:
:root {
  --ink: #16263b;
  --muted: #64748b;
  --paper: #fffdf8;
  --line: #d9e2ec;
  --sky: #e7f2ff;
  --blue: #2774c8;
  --mint: #dff6ea;
  --green: #16724a;
  --amber-bg: #fff0c7;
  --amber: #9a5a00;
}

.launch-card {
  box-sizing: border-box;
  width: 500px;
  padding: 16px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.brief-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.heading-group {
  min-width: 0;
}

.eyebrow,
.panel-kicker {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: 0.08em;
}

.brief-title {
  margin: 4px 0 0;
  font-size: 22px;
  font-weight: 750;
  line-height: 1.1;
  letter-spacing: -0.03em;
}

.status {
  flex: 0 0 auto;
  padding: 6px 9px;
  color: var(--green);
  background: var(--mint);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
  line-height: 1;
}

.site-line {
  margin: 10px 0 12px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
  line-height: 1.3;
}

.site-divider {
  margin: 0 4px;
  color: var(--line);
}

.brief-grid {
  display: grid;
  grid-template-columns: 1.08fr 0.92fr;
  gap: 10px;
}

.telemetry,
.checklist {
  box-sizing: border-box;
  min-height: 132px;
  padding: 12px;
  border-radius: 12px;
}

.telemetry {
  background: var(--sky);
}

.metrics-row {
  display: flex;
  gap: 6px;
  margin-top: 10px;
}

.metric {
  flex: 1;
  min-width: 0;
  padding: 8px 6px;
  text-align: center;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 8px;
}

.metric-value,
.metric-label {
  display: block;
}

.metric-value {
  font-size: 15px;
  font-weight: 800;
  line-height: 1;
  letter-spacing: -0.03em;
}

.metric-label {
  margin-top: 4px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 600;
  line-height: 1;
}

.flight-path {
  margin-top: 12px;
}

.path-label,
.check-head,
.brief-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.path-title,
.path-value {
  font-size: 11px;
  font-weight: 700;
  line-height: 1.2;
}

.path-value {
  color: var(--blue);
}

.bar {
  display: block;
  height: 6px;
  margin-top: 6px;
  overflow: hidden;
  background: var(--paper);
  border-radius: 999px;
}

.bar-fill {
  display: block;
  width: 72%;
  height: 100%;
  background: var(--blue);
  border-radius: inherit;
}

.checklist {
  background: var(--mint);
}

.section-title {
  margin: 0;
  font-size: 13px;
  font-weight: 800;
  line-height: 1.2;
}

.count {
  padding: 3px 6px;
  color: var(--green);
  background: var(--paper);
  border-radius: 5px;
  font-size: 10px;
  font-weight: 800;
  line-height: 1;
}

.check-list {
  display: grid;
  gap: 7px;
  margin: 10px 0 0;
  padding: 0;
  list-style: none;
}

.check-item {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 11px;
  font-weight: 650;
  line-height: 1.2;
}

.check-dot {
  display: grid;
  flex: 0 0 16px;
  width: 16px;
  height: 16px;
  place-items: center;
  border-radius: 50%;
  font-size: 10px;
  font-weight: 900;
}

.ready {
  color: var(--green);
  background: var(--paper);
}

.pending {
  color: var(--amber);
  background: var(--amber-bg);
}

.brief-footer {
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.footer-note {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
  line-height: 1.2;
}

.launch-button {
  padding: 8px 11px;
  color: var(--paper);
  background: var(--ink);
  border: 0;
  border-radius: 8px;
  font-size: 11px;
  font-weight: 800;
  line-height: 1;
}
